/// A query limit of 0 or above 200 is a problem; 200 and none are not.
#[test]
fn schema_limit_problems_example_1() {
    let schema: types::TenantSchema = {
        let mut fixture = fixture_fx_tenant_schema_5();
        fixture.queries.insert(
            types::QueryId("a_zero".to_string()),
            types::QueryDef {
                id: types::QueryId("a_zero".to_string()),
                object: types::ObjectTypeId("note".to_string()),
                filter: None,
                params: std::collections::BTreeSet::new(),
                order: Vec::new(),
                limit: Some(0),
                aggregates: None,
                declared_fields: None,
            },
        );
        fixture.queries.insert(
            types::QueryId("b_ok".to_string()),
            types::QueryDef {
                id: types::QueryId("b_ok".to_string()),
                object: types::ObjectTypeId("note".to_string()),
                filter: None,
                params: std::collections::BTreeSet::new(),
                order: Vec::new(),
                limit: Some(200),
                aggregates: None,
                declared_fields: None,
            },
        );
        fixture.queries.insert(
            types::QueryId("c_big".to_string()),
            types::QueryDef {
                id: types::QueryId("c_big".to_string()),
                object: types::ObjectTypeId("note".to_string()),
                filter: None,
                params: std::collections::BTreeSet::new(),
                order: Vec::new(),
                limit: Some(201),
                aggregates: None,
                declared_fields: None,
            },
        );
        fixture.queries.insert(
            types::QueryId("d_none".to_string()),
            types::QueryDef {
                id: types::QueryId("d_none".to_string()),
                object: types::ObjectTypeId("note".to_string()),
                filter: None,
                params: std::collections::BTreeSet::new(),
                order: Vec::new(),
                limit: None,
                aggregates: None,
                declared_fields: None,
            },
        );
        fixture
    };
    let want_: Vec<String> = vec![
        "limit: query a_zero declares a limit outside 1 to 200".to_string(),
        "limit: query c_big declares a limit outside 1 to 200".to_string(),
    ];
    assert_eq!(schema_limit_problems(&schema), want_);
}

