/// An event that is no record event binds nothing.
#[test]
fn trigger_scopes_of_example_8() {
    let t: types::TenantState = fixture_fx_tenant_state_26();
    let principal: types::Principal =
        types::Principal::User(types::PrincipalId("automation:award".to_string()));
    let now: crate::prelude::Timestamp = crate::prelude::Timestamp(6000);
    let body: types::EventBody = types::EventBody::SchemaChanged {
        version: types::SchemaVersion(3),
        summary: Vec::new(),
        grandfathered: 0,
    };
    let want_: Option<types::TriggerScopes> = None;
    assert_eq!(trigger_scopes_of(&t, &principal, now, &body), Ok(want_));
}

