/// Example 1 of `split-publishes`.
#[test]
fn split_publishes_example_1() {
    let effects: Vec<types::Effect> = Vec::new();
    let want_: types::LeadEffects = types::LeadEffects {
        lead: Vec::new(),
        rest: Vec::new(),
        open: true,
    };
    assert_eq!(split_publishes(&effects), want_);
}

/// Example 2 of `split-publishes`.
#[test]
fn split_publishes_example_2() {
    let effects: Vec<types::Effect> = vec![
        types::Effect::Publish { seq: 1 },
        types::Effect::RevokeSessions {
            principal: types::PrincipalId("alpha:ed".to_string()),
        },
        types::Effect::Publish { seq: 2 },
    ];
    let want_: types::LeadEffects = types::LeadEffects {
        lead: vec![types::Effect::Publish { seq: 1 }],
        rest: vec![
            types::Effect::RevokeSessions {
                principal: types::PrincipalId("alpha:ed".to_string()),
            },
            types::Effect::Publish { seq: 2 },
        ],
        open: false,
    };
    assert_eq!(split_publishes(&effects), want_);
}

/// Example 3 of `split-publishes`.
#[test]
fn split_publishes_example_3() {
    let effects: Vec<types::Effect> = vec![
        types::Effect::Publish { seq: 1 },
        types::Effect::Publish { seq: 2 },
    ];
    let want_: types::LeadEffects = types::LeadEffects {
        lead: vec![
            types::Effect::Publish { seq: 1 },
            types::Effect::Publish { seq: 2 },
        ],
        rest: Vec::new(),
        open: true,
    };
    assert_eq!(split_publishes(&effects), want_);
}

